    selected=['normative_records','optional_records','no_required_revision_records','optional_facets','policy_records','limit_records','aliases_tombstones_and_accepted_negative_hypotheses','accepted_facts','batch_contracts','dependency_graph','execution_phases','historical_qualification','state_semantics']
    seen={};fields=[];unique=[]
    def walk(x,p):
        if isinstance(x,dict):
            for k,v in x.items():walk(v,p+'/'+k.replace('~','~0').replace('/','~1'))
        elif isinstance(x,list):
